return 0
}
if (r == null) {
return 0
}
let ac = fqchapters(a.data ?? a)
let rc = fqchapters(r.data ?? r)
if (len(ac) == 0) {
return 0
}
if (len(rc) == 0) {
return 0
}
let rk = []
let j = 0
while (j < len(rc)) {
rk = push(rk, fqrealkey(rc[j].title))
j = j + 1
}
let hit = 0
let i = 0
while (i < len(ac)) {
let k = fqrealkey(ac[i].title)
let m = 0
let found = false
while (m < len(rk)) {
if (rk[m] == k) {
found = true
m = len(rk)
}
m = m + 1
}
if (found) {
hit = hit + 1
}
i = i + 1
}
return hit * 100 / len(ac)
}
// 分类树 → 男频/女频/出版 三组（tab_type=2 听书分类树）
fn fqcats(d) {
  let root = default(get(d, 'data', null), d)
  let gs = ['男频|boy_category', '女频|girl_category', '出版|publish_category']
  let out = []
  for g in gs {
    let ab = split(str(g), '|')
    push(out, { category_name: str(ab[0]) })
    for x in default(get(root, str(ab[1]), null), []) {
      if (str(x.dim) == '1') {
        push(out, { category_name: x.category_name, category_id: x.category_id })
      }
    }
  }
  return out
}
// 分类 → 书单地址（book_list/v1 免签名）
fn fqsearchone(d, tab) {
  let ts = d.search_tabs
  if (ts == null) { return [] }
  let out = []
  for t in ts {
    if (str(t.tab_type) != str(tab)) { continue }
    let arr = t.data
    if (arr == null) { return [] }
    let vals = []
    if (typeOf(arr) == 'list') { vals = arr }
    else { for k in keys(arr) { push(vals, arr[k]) } }
    for v in vals {
      let b = fqbd(v)
      let nm = str(default(b.book_name, ''))
      if (nm == '' || nm == 'undefined' || nm == 'null') { continue }
      push(out, b)
    }
    return out
  }
  return []
}

